// mic_custom_capturer_linux.h
//
// [chatpapol 48k — Stage 2 / Linux] Capturador de micro nativo que alimenta la
// fuente de audio kCustom creada en Stage 1 (CreateCustomAudioTrack). Lee PCM
// del servidor de audio del sistema a 48 kHz / mono / S16 y lo inyecta en la
// RTCAudioSource via CaptureFrame, SIN pasar por el APM de WebRTC (que baja a
// 16 kHz). Resultado: voz fullband 48 kHz (calidad Discord).
//
// Backend: PulseAudio Simple API (libpulse-simple). Corre tal cual sobre
// PulseAudio y sobre PipeWire (via pipewire-pulse, default en CachyOS), en X11
// o Wayland. Si libpulse-simple no esta disponible en build, el .cc compila
// como no-op (ver guarda CHATPAPOL_HAVE_PULSE en el CMake).
//
// AEC: al saltarse el APM se pierde la cancelacion de eco -> AURICULARES
// OBLIGATORIOS (este capturador NO implementa AEC).
//
// El header NO expone tipos de PulseAudio: el puntero pa_simple vive en el .cc
// (PIMPL), de modo que el resto del plugin puede incluir este header sin
// arrastrar libpulse.
#ifndef CHATPAPOL_MIC_CUSTOM_CAPTURER_LINUX_H_
#define CHATPAPOL_MIC_CUSTOM_CAPTURER_LINUX_H_

#include <atomic>
#include <string>
#include <thread>

// Forward-declare la fuente de audio de libwebrtc (no incluimos el header aqui
// para mantener el .h liviano; el .cc incluye rtc_audio_source.h).
namespace libwebrtc {
class RTCAudioSource;
}  // namespace libwebrtc

namespace flutter_webrtc_plugin {

// Captura mono 48 kHz S16 en un hilo dedicado y llama
// source->CaptureFrame(data, 16, 48000, 1, 480) cada ~10 ms.
//
// Uso:
//   MicCustomCapturerLinux cap;
//   cap.Start(source);   // source = custom_audio_sources_[track_id].get()
//   ...
//   cap.Stop();          // idempotente; tambien lo llama el destructor
class MicCustomCapturerLinux {
 public:
  // Parametros fijos del formato que se inyecta a la fuente kCustom.
  static constexpr int kSampleRate = 48000;
  static constexpr int kChannels = 1;
  static constexpr int kBitsPerSample = 16;
  // 10 ms a 48 kHz = 480 frames (multiplo amigable para RNNoise/voicefx 48k).
  static constexpr int kFramesPer10ms = 480;

  MicCustomCapturerLinux();
  ~MicCustomCapturerLinux();

  MicCustomCapturerLinux(const MicCustomCapturerLinux&) = delete;
  MicCustomCapturerLinux& operator=(const MicCustomCapturerLinux&) = delete;

  // Arranca la captura alimentando |source|. |source| debe seguir vivo hasta
  // Stop() (el llamador retiene el scoped_refptr en custom_audio_sources_).
  // |device| vacio = device de captura por defecto del servidor. Devuelve
  // false si ya estaba corriendo, si source es null, o si no hay backend.
  bool Start(libwebrtc::RTCAudioSource* source,
             const std::string& device = std::string());

  // Para el hilo y libera el backend. Idempotente.
  void Stop();

  bool IsRunning() const { return running_.load(std::memory_order_acquire); }

 private:
  void CaptureLoop(std::string device);

  libwebrtc::RTCAudioSource* source_ = nullptr;  // no-owning
  std::thread thread_;
  std::atomic<bool> running_{false};
  std::atomic<bool> stop_requested_{false};
};

}  // namespace flutter_webrtc_plugin

#endif  // CHATPAPOL_MIC_CUSTOM_CAPTURER_LINUX_H_

// mic_custom_capturer_linux.cc — ver mic_custom_capturer_linux.h.
//
// Backend PulseAudio Simple API. Si CHATPAPOL_HAVE_PULSE no esta definido (la
// lib de dev no estaba presente en build), todo compila como no-op para no
// romper el build; en ese caso Start() devuelve false.
#include "mic_custom_capturer_linux.h"

#include <chrono>
#include <cstdint>
#include <vector>

#include "rtc_audio_source.h"  // libwebrtc::RTCAudioSource::CaptureFrame

#ifdef CHATPAPOL_HAVE_PULSE
#include <pulse/error.h>
#include <pulse/simple.h>
#endif

namespace flutter_webrtc_plugin {

MicCustomCapturerLinux::MicCustomCapturerLinux() = default;

MicCustomCapturerLinux::~MicCustomCapturerLinux() {
  Stop();
}

bool MicCustomCapturerLinux::Start(libwebrtc::RTCAudioSource* source,
                                   const std::string& device) {
  if (source == nullptr) return false;
  if (running_.load(std::memory_order_acquire)) return false;

#ifndef CHATPAPOL_HAVE_PULSE
  // Sin backend de captura compilado: no-op (la voz seguira muda hasta que se
  // instale libpulse-simple-dev y se recompile el plugin).
  (void)device;
  return false;
#else
  source_ = source;
  stop_requested_.store(false, std::memory_order_release);
  running_.store(true, std::memory_order_release);
  thread_ = std::thread(&MicCustomCapturerLinux::CaptureLoop, this, device);
  return true;
#endif
}

void MicCustomCapturerLinux::Stop() {
  stop_requested_.store(true, std::memory_order_release);
  if (thread_.joinable()) {
    // pa_simple_read es bloqueante hasta ~10 ms, asi que el loop revisa
    // stop_requested_ y retorna en breve.
    thread_.join();
  }
  running_.store(false, std::memory_order_release);
  source_ = nullptr;
}

#ifdef CHATPAPOL_HAVE_PULSE

void MicCustomCapturerLinux::CaptureLoop(std::string device) {
  // Formato exacto que pedimos al servidor; el servidor (Pulse/PipeWire)
  // resamplea/convierte desde el formato nativo del device.
  pa_sample_spec ss;
  ss.format = PA_SAMPLE_S16LE;
  ss.rate = static_cast<uint32_t>(kSampleRate);
  ss.channels = static_cast<uint8_t>(kChannels);

  const size_t bytes_per_chunk =
      static_cast<size_t>(kFramesPer10ms) * kChannels * sizeof(int16_t);

  // Latencia objetivo baja: pedimos fragmentos de ~10 ms. -1 en el resto deja
  // que el servidor elija buenos defaults. tlength/maxlength/prebuf/minreq solo
  // aplican a playback, pero la struct es compartida; se ignoran en RECORD.
  pa_buffer_attr battr;
  battr.maxlength = static_cast<uint32_t>(-1);
  battr.tlength = static_cast<uint32_t>(-1);
  battr.prebuf = static_cast<uint32_t>(-1);
  battr.minreq = static_cast<uint32_t>(-1);
  battr.fragsize = static_cast<uint32_t>(bytes_per_chunk);  // ~10 ms

  std::vector<int16_t> buf(static_cast<size_t>(kFramesPer10ms) * kChannels);
  const char* dev = device.empty() ? nullptr : device.c_str();

  pa_simple* pa = nullptr;

  while (!stop_requested_.load(std::memory_order_acquire)) {
    // (Re)conectar si hace falta. Cubre arranque y cambios de default device.
    if (pa == nullptr) {
      int err = 0;
      pa = pa_simple_new(
          /*server=*/nullptr,
          /*name=*/"chatpapol",
          /*dir=*/PA_STREAM_RECORD,
          /*dev=*/dev,
          /*stream_name=*/"mic-48k",
          /*ss=*/&ss,
          /*map=*/nullptr,
          /*attr=*/&battr,
          /*error=*/&err);
      if (pa == nullptr) {
        // No se pudo conectar (servidor caido / device invalido). Reintentar
        // tras una pausa, salvo que nos pidan parar.
        for (int i = 0; i < 5 && !stop_requested_.load(std::memory_order_acquire);
             ++i) {
          std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }
        continue;
      }
    }

    int err = 0;
    if (pa_simple_read(pa, buf.data(), bytes_per_chunk, &err) < 0) {
      // Error de lectura (p.ej. el device desaparecio): cerrar y reconectar.
      pa_simple_free(pa);
      pa = nullptr;
      std::this_thread::sleep_for(std::chrono::milliseconds(100));
      continue;
    }

    // Inyectar a la fuente kCustom: 48 kHz, mono, S16, 480 frames (~10 ms).
    // No pasa por APM -> fullband. CaptureFrame copia/consume el buffer.
    if (source_ != nullptr) {
      source_->CaptureFrame(buf.data(), kBitsPerSample, kSampleRate,
                            static_cast<size_t>(kChannels),
                            static_cast<size_t>(kFramesPer10ms));
    }
  }

  if (pa != nullptr) {
    pa_simple_free(pa);
    pa = nullptr;
  }
}

#else  // !CHATPAPOL_HAVE_PULSE

void MicCustomCapturerLinux::CaptureLoop(std::string /*device*/) {
  // Sin backend: nada que hacer (Start nunca arranca el hilo en este caso).
}

#endif  // CHATPAPOL_HAVE_PULSE

}  // namespace flutter_webrtc_plugin

#ifndef MIC_CUSTOM_CAPTURER_WIN_H_
#define MIC_CUSTOM_CAPTURER_WIN_H_

#ifdef _WIN32

#include <atomic>
#include <mutex>
#include <string>
#include <thread>
#include <vector>

#include <audioclient.h>
#include <mmdeviceapi.h>
#include <windows.h>

#include "rtc_audio_source.h"
#include "rtc_types.h"

namespace flutter_webrtc_plugin {

using namespace libwebrtc;

// [chatpapol 48k — Stage 2 / Windows] Capturador de MICRO a 48 kHz fullband
// para la pista kCustom. Abre el endpoint de CAPTURA (eCapture) en shared mode
// vía WASAPI (GetMixFormat suele dar 48 kHz float), convierte a int16 mono a la
// tasa nativa del endpoint y alimenta la fuente kCustom con CaptureFrame, SIN
// pasar por el APM (que reamuestrea a 16k band-0). voicefx/RNNoise se aplicarán
// a 48k FUERA del APM en un paso posterior.
//
// Clona el desacople anti-crash del ApplicationLoopbackCapturer (ring buffer +
// hilo de captura + hilo feeder), pero NO es un LoopbackCapturer: el micro no
// usa el flag LOOPBACK ni ActivateAudioInterfaceAsync; usa la activación
// clásica IMMDevice::Activate(IID_IAudioClient).
//
// Sin APM no hay AEC: el monitor de altavoces produciría eco -> AURICULARES
// OBLIGATORIOS.
class MicCustomCapturer {
 public:
  MicCustomCapturer();
  ~MicCustomCapturer();

  // endpoint_id vacío => micro por defecto (rol eCommunications). En otro caso,
  // el IMMDevice endpoint id (el mismo string que devuelve IMMDevice::GetId).
  void SetDeviceId(const std::string& endpoint_id) { device_id_ = endpoint_id; }

  // Arranca la captura y empieza a empujar PCM int16 mono 48k a |source|.
  // Devuelve false si no se pudo inicializar WASAPI. Idempotente si ya corre.
  bool Start(scoped_refptr<RTCAudioSource> source);

  // Detiene la captura y libera recursos WASAPI. Idempotente.
  void Stop();

  bool running() const { return running_; }

 private:
  // Abre el endpoint de captura y deja audio_client_ inicializado + mix_format_
  // poblado. Devuelve true en éxito. Corre en el hilo que llama a Start().
  bool InitCaptureEndpoint();

  void CaptureThread();
  void FeederThread();

  scoped_refptr<RTCAudioSource> source_;
  std::atomic<bool> running_{false};
  std::thread capture_thread_;
  std::thread feeder_thread_;

  std::string device_id_;  // vacío => default eCommunications

  IAudioClient* audio_client_ = nullptr;
  IAudioCaptureClient* capture_client_ = nullptr;
  WAVEFORMATEX* mix_format_ = nullptr;

  // WASAPI señala este evento cuando hay un buffer de captura listo.
  HANDLE buffer_ready_event_ = nullptr;

  // Ring buffer que desacopla el hilo de captura WASAPI del hilo feeder
  // (WebRTC). CaptureThread escribe; FeederThread lee. Imprescindible: llamar
  // CaptureFrame desde el callback de WASAPI dispara el race-checker del
  // AudioSendStream (mismo motivo que en el loopback).
  std::mutex ring_mutex_;
  std::vector<int16_t> ring_buf_;  // capacidad: ring_capacity_frames_ * cached_out_channels_
  size_t ring_capacity_frames_ = 0;
  size_t ring_write_frame_ = 0;
  size_t ring_read_frame_ = 0;
  size_t ring_frames_avail_ = 0;

  // Formato cacheado desde mix_format_ para el FeederThread.
  int cached_sample_rate_ = 0;
  size_t cached_out_channels_ = 0;  // siempre 1 (mono)

  // ----- Extractores muestra -> int16 (idénticos a los del loopback) -----
  typedef int16_t (*SampleExtractor)(const BYTE*);

  static int16_t ExtractFloat32(const BYTE* ptr) {
    float v = *reinterpret_cast<const float*>(ptr);
    if (v > 1.0f) v = 1.0f;
    if (v < -1.0f) v = -1.0f;
    return static_cast<int16_t>(v * 32767.0f);
  }
  static int16_t ExtractInt32(const BYTE* ptr) {
    return static_cast<int16_t>((*reinterpret_cast<const INT32*>(ptr)) >> 16);
  }
  static int16_t ExtractInt24(const BYTE* ptr) {
    INT32 s = static_cast<INT32>(ptr[0] | (ptr[1] << 8) | (ptr[2] << 16));
    if (s & 0x00800000) s |= static_cast<INT32>(0xFF000000);  // sign-extend
    return static_cast<int16_t>(s >> 8);
  }
  static int16_t ExtractInt16(const BYTE* ptr) {
    return *reinterpret_cast<const int16_t*>(ptr);
  }
};

}  // namespace flutter_webrtc_plugin

#endif  // _WIN32
#endif  // MIC_CUSTOM_CAPTURER_WIN_H_

#ifdef _WIN32

#include "mic_custom_capturer_win.h"

#include <avrt.h>
#include <chrono>
#include <cstring>
#include <iostream>
#include <timeapi.h>

#include <functiondiscoverykeys_devpkey.h>

namespace flutter_webrtc_plugin {

MicCustomCapturer::MicCustomCapturer() = default;

MicCustomCapturer::~MicCustomCapturer() {
  Stop();
}

// ---------------------------------------------------------------------------
// Start
// ---------------------------------------------------------------------------
bool MicCustomCapturer::Start(scoped_refptr<RTCAudioSource> source) {
  if (running_) return true;

  source_ = source;

  if (!InitCaptureEndpoint()) {
    std::cerr << "[MicCustomCapturer] InitCaptureEndpoint failed.\n";
    Stop();
    return false;
  }

  buffer_ready_event_ = CreateEvent(nullptr, FALSE, FALSE, nullptr);
  if (buffer_ready_event_ == nullptr) {
    Stop();
    return false;
  }

  HRESULT hr = audio_client_->SetEventHandle(buffer_ready_event_);
  if (FAILED(hr)) {
    std::cerr << "[MicCustomCapturer] SetEventHandle failed: 0x" << std::hex
              << hr << "\n";
    Stop();
    return false;
  }

  hr = audio_client_->GetService(IID_PPV_ARGS(&capture_client_));
  if (FAILED(hr)) {
    std::cerr << "[MicCustomCapturer] GetService(IAudioCaptureClient) failed: 0x"
              << std::hex << hr << "\n";
    Stop();
    return false;
  }

  // Cachear formato para el FeederThread (mix_format_ vive en este hilo).
  cached_sample_rate_ = static_cast<int>(mix_format_->nSamplesPerSec);
  cached_out_channels_ = 1;  // mono

  // Ring buffer: 500 ms de holgura de int16 mono.
  {
    const size_t frames_per_20ms =
        static_cast<size_t>(cached_sample_rate_) / 50;
    ring_capacity_frames_ = 25 * frames_per_20ms;  // 500 ms
    ring_buf_.assign(ring_capacity_frames_ * cached_out_channels_, int16_t{0});
    ring_write_frame_ = 0;
    ring_read_frame_ = 0;
    ring_frames_avail_ = 0;
  }

  hr = audio_client_->Start();
  if (FAILED(hr)) {
    std::cerr << "[MicCustomCapturer] IAudioClient::Start failed: 0x"
              << std::hex << hr << "\n";
    Stop();
    return false;
  }

  running_ = true;
  capture_thread_ = std::thread(&MicCustomCapturer::CaptureThread, this);
  feeder_thread_ = std::thread(&MicCustomCapturer::FeederThread, this);
  // std::cout << "[MicCustomCapturer] Capture started ("
  //           << mix_format_->nSamplesPerSec << " Hz, "
  //           << mix_format_->nChannels << " ch in -> 1 ch out, "
  //           << mix_format_->wBitsPerSample << "-bit).\n";
  return true;
}

// ---------------------------------------------------------------------------
// Stop
// ---------------------------------------------------------------------------
void MicCustomCapturer::Stop() {
  const bool was_running = running_.exchange(false);

  // Despertar el hilo de captura para que salga del WaitForSingleObject.
  if (buffer_ready_event_ != nullptr) {
    SetEvent(buffer_ready_event_);
  }
  if (capture_thread_.joinable()) capture_thread_.join();
  if (feeder_thread_.joinable()) feeder_thread_.join();
  (void)was_running;

  if (audio_client_) {
    audio_client_->Stop();
    audio_client_->Release();
    audio_client_ = nullptr;
  }
  if (capture_client_) {
    capture_client_->Release();
    capture_client_ = nullptr;
  }
  if (mix_format_) {
    CoTaskMemFree(mix_format_);
    mix_format_ = nullptr;
  }
  if (buffer_ready_event_ != nullptr) {
    CloseHandle(buffer_ready_event_);
    buffer_ready_event_ = nullptr;
  }
  source_ = nullptr;
  // std::cout << "[MicCustomCapturer] Capture stopped.\n";
}

// ---------------------------------------------------------------------------
// InitCaptureEndpoint
// Abre el endpoint de captura (eCapture) en shared mode y deja audio_client_
// inicializado + mix_format_ poblado.
// ---------------------------------------------------------------------------
bool MicCustomCapturer::InitCaptureEndpoint() {
  // Apartment para esta operación de inicialización. WASAPI funciona en MTA;
  // CoInitialize puede devolver S_FALSE si ya estaba inicializado en este
  // hilo: en ese caso NO debemos llamar CoUninitialize aquí.
  HRESULT co = CoInitializeEx(nullptr, COINIT_MULTITHREADED);
  const bool need_couninit = SUCCEEDED(co) && co != S_FALSE;

  IMMDeviceEnumerator* enumerator = nullptr;
  IMMDevice* device = nullptr;
  bool ok = false;

  HRESULT hr = CoCreateInstance(__uuidof(MMDeviceEnumerator), nullptr,
                                CLSCTX_ALL, IID_PPV_ARGS(&enumerator));
  if (SUCCEEDED(hr)) {
    if (!device_id_.empty()) {
      // Endpoint id explícito (UTF-8 -> UTF-16).
      int wlen = MultiByteToWideChar(CP_UTF8, 0, device_id_.c_str(), -1,
                                     nullptr, 0);
      if (wlen > 0) {
        std::vector<wchar_t> wid(static_cast<size_t>(wlen));
        MultiByteToWideChar(CP_UTF8, 0, device_id_.c_str(), -1, wid.data(),
                            wlen);
        hr = enumerator->GetDevice(wid.data(), &device);
      } else {
        hr = E_INVALIDARG;
      }
      if (FAILED(hr)) {
        std::cerr << "[MicCustomCapturer] GetDevice(id) failed: 0x" << std::hex
                  << hr << " — usando micro por defecto.\n";
        device = nullptr;
      }
    }
    if (device == nullptr) {
      // Por defecto: rol de comunicaciones (el micro "de llamadas").
      hr = enumerator->GetDefaultAudioEndpoint(eCapture, eCommunications,
                                               &device);
      if (FAILED(hr)) {
        hr = enumerator->GetDefaultAudioEndpoint(eCapture, eConsole, &device);
      }
    }
  }

  if (SUCCEEDED(hr) && device) {
    hr = device->Activate(__uuidof(IAudioClient), CLSCTX_ALL, nullptr,
                          reinterpret_cast<void**>(&audio_client_));
  }

  WAVEFORMATEX* fmt = nullptr;
  if (SUCCEEDED(hr) && audio_client_) {
    hr = audio_client_->GetMixFormat(&fmt);  // shared mode: suele dar 48k float
  }

  if (SUCCEEDED(hr) && audio_client_ && fmt) {
    // Buffer de 200 ms (en unidades de 100 ns). Shared mode ignora el tamaño
    // exacto y usa el periodo del motor, pero un valor sano evita sorpresas.
    const REFERENCE_TIME buffer_duration = 2000000LL;  // 200 ms
    hr = audio_client_->Initialize(
        AUDCLNT_SHAREMODE_SHARED, AUDCLNT_STREAMFLAGS_EVENTCALLBACK,
        buffer_duration, 0, fmt, nullptr);
    if (SUCCEEDED(hr)) {
      mix_format_ = fmt;  // se libera en Stop() con CoTaskMemFree
      fmt = nullptr;
      ok = true;
    } else {
      std::cerr << "[MicCustomCapturer] IAudioClient::Initialize failed: 0x"
                << std::hex << hr << "\n";
    }
  } else {
    std::cerr << "[MicCustomCapturer] endpoint init failed: 0x" << std::hex
              << hr << "\n";
  }

  if (fmt) CoTaskMemFree(fmt);
  if (device) device->Release();
  if (enumerator) enumerator->Release();

  if (!ok && audio_client_) {
    audio_client_->Release();
    audio_client_ = nullptr;
  }

  if (need_couninit) CoUninitialize();
  return ok;
}

// ---------------------------------------------------------------------------
// CaptureThread
// Lee paquetes de WASAPI, convierte a int16 mono y los escribe en el ring
// buffer. NO llama a CaptureFrame (eso lo hace FeederThread), para desacoplar
// el timing del callback WASAPI del hilo de audio de WebRTC.
// ---------------------------------------------------------------------------
void MicCustomCapturer::CaptureThread() {
  CoInitializeEx(nullptr, COINIT_MULTITHREADED);

  DWORD task_index = 0;
  HANDLE task = AvSetMmThreadCharacteristicsW(L"Audio", &task_index);

  const size_t in_channels = mix_format_->nChannels;
  const size_t out_channels = cached_out_channels_;  // 1
  const int bits = mix_format_->wBitsPerSample;

  bool is_float = (mix_format_->wFormatTag == WAVE_FORMAT_IEEE_FLOAT);
  if (mix_format_->wFormatTag == WAVE_FORMAT_EXTENSIBLE) {
    auto* ext = reinterpret_cast<WAVEFORMATEXTENSIBLE*>(mix_format_);
    static const GUID kSubtypeFloat = {
        0x00000003, 0x0000, 0x0010,
        {0x80, 0x00, 0x00, 0xaa, 0x00, 0x38, 0x9b, 0x71}};
    is_float = (ext->SubFormat == kSubtypeFloat);
  }

  SampleExtractor extractor = ExtractInt16;  // fallback
  if (is_float && bits == 32) {
    extractor = ExtractFloat32;
  } else if (!is_float && bits == 32) {
    extractor = ExtractInt32;
  } else if (!is_float && bits == 24) {
    extractor = ExtractInt24;
  }

  const size_t bytes_per_sample = static_cast<size_t>(bits) / 8;

  std::vector<int16_t> conv;  // buffer temporal de conversión (mono)

  while (running_) {
    DWORD wait_result = WaitForSingleObject(buffer_ready_event_, 200);
    if (!running_) break;
    if (wait_result == WAIT_TIMEOUT) continue;
    if (wait_result != WAIT_OBJECT_0) break;

    UINT32 packet_size = 0;
    while (SUCCEEDED(capture_client_->GetNextPacketSize(&packet_size)) &&
           packet_size > 0) {
      BYTE* data = nullptr;
      UINT32 num_frames = 0;
      DWORD flags = 0;

      HRESULT hr = capture_client_->GetBuffer(&data, &num_frames, &flags,
                                              nullptr, nullptr);
      if (FAILED(hr)) break;

      if (num_frames > 0) {
        const bool silent = (flags & AUDCLNT_BUFFERFLAGS_SILENT) != 0;
        if (!silent && data != nullptr) {
          conv.resize(num_frames * out_channels);
          for (size_t f = 0; f < num_frames; ++f) {
            const BYTE* frame_ptr =
                data + (f * in_channels * bytes_per_sample);
            // Down-mix a mono: promedio de todos los canales de entrada.
            int32_t acc = 0;
            for (size_t ch = 0; ch < in_channels; ++ch) {
              acc += extractor(frame_ptr + ch * bytes_per_sample);
            }
            conv[f] = static_cast<int16_t>(
                acc / static_cast<int32_t>(in_channels > 0 ? in_channels : 1));
          }
        }
        {
          std::lock_guard<std::mutex> lock(ring_mutex_);
          for (size_t f = 0; f < num_frames; ++f) {
            if (ring_frames_avail_ >= ring_capacity_frames_) {
              ring_read_frame_ = (ring_read_frame_ + 1) % ring_capacity_frames_;
              --ring_frames_avail_;
            }
            const size_t write_pos = ring_write_frame_ * out_channels;
            if (silent) {
              std::memset(ring_buf_.data() + write_pos, 0,
                          out_channels * sizeof(int16_t));
            } else {
              std::memcpy(ring_buf_.data() + write_pos,
                          conv.data() + f * out_channels,
                          out_channels * sizeof(int16_t));
            }
            ring_write_frame_ = (ring_write_frame_ + 1) % ring_capacity_frames_;
            ++ring_frames_avail_;
          }
        }
      }
      capture_client_->ReleaseBuffer(num_frames);
    }
  }

  if (task) AvRevertMmThreadCharacteristics(task);
  CoUninitialize();
}

// ---------------------------------------------------------------------------
// FeederThread
// Dispara cada 10 ms con un waitable timer (paced a wall-clock) y llama a
// CaptureFrame con exactamente frames_per_10ms muestras del ring buffer.
// Pre-buffer de 160 ms, hard-cap de 200 ms y drift-skip — mismo diseño de
// jitter buffer que el loopback (evita chops por stalls de WASAPI y evita
// sobrellenar el jitter buffer del receptor).
// ---------------------------------------------------------------------------
void MicCustomCapturer::FeederThread() {
  CoInitializeEx(nullptr, COINIT_MULTITHREADED);

  DWORD task_index = 0;
  HANDLE task = AvSetMmThreadCharacteristicsW(L"Audio", &task_index);

  const int sample_rate = cached_sample_rate_;
  const size_t out_channels = 1;

  // 480 muestras = una trama de 10 ms a 48 kHz.
  const size_t frames_per_10ms = static_cast<size_t>(sample_rate) / 100;
  if (frames_per_10ms == 0) {  // tasa absurda: salir limpio
    if (task) AvRevertMmThreadCharacteristics(task);
    CoUninitialize();
    return;
  }

  const size_t target_prebuf = 16 * frames_per_10ms;  // 160 ms de relleno
  const size_t max_buffered = 20 * frames_per_10ms;   // 200 ms tope duro

  std::vector<int16_t> feed(frames_per_10ms * out_channels, int16_t{0});
  bool prebuffering = true;

  using FClock = std::chrono::steady_clock;

  HANDLE timer = CreateWaitableTimerW(nullptr, FALSE, nullptr);
  LARGE_INTEGER due = {};
  due.QuadPart = -100000LL;  // 10 ms inicial (unidades de 100 ns)
  SetWaitableTimer(timer, &due, 10, nullptr, nullptr, FALSE);

  timeBeginPeriod(10);

  auto feeder_start = FClock::now();
  bool feeder_start_valid = false;
  int64_t total_frames_del = 0;

  while (running_) {
    if (WaitForSingleObject(timer, 40) == WAIT_FAILED) break;
    if (!running_) break;

    std::fill(feed.begin(), feed.end(), int16_t{0});

    // Drift compensation: si vamos más de una trama de 10 ms por delante del
    // wall-clock, saltar este tick (no consumir del ring ni llamar
    // CaptureFrame) para mantener el ritmo de envío a la tasa nominal.
    if (feeder_start_valid) {
      const double elapsed_sec =
          std::chrono::duration<double>(FClock::now() - feeder_start).count();
      const int64_t expected_frm =
          static_cast<int64_t>(elapsed_sec * sample_rate);
      if (total_frames_del >
          expected_frm + static_cast<int64_t>(frames_per_10ms)) {
        continue;
      }
    }

    {
      std::lock_guard<std::mutex> lock(ring_mutex_);

      // Hard cap: recortar las tramas más viejas para mantener latencia <200ms.
      if (ring_frames_avail_ > max_buffered) {
        const size_t drop = ring_frames_avail_ - max_buffered;
        ring_read_frame_ = (ring_read_frame_ + drop) % ring_capacity_frames_;
        ring_frames_avail_ -= drop;
      }

      // Pre-buffer de arranque: esperar a tener 160 ms en el ring.
      if (prebuffering) {
        if (ring_frames_avail_ >= target_prebuf) {
          prebuffering = false;
          feeder_start = FClock::now();  // arrancar el reloj de drift AHORA
          feeder_start_valid = true;
        } else {
          continue;  // sigue acumulando — saltar CaptureFrame este tick
        }
      }

      // Consumir hasta 10 ms del ring por tick (rellena con ceros si falta).
      if (ring_frames_avail_ > 0) {
        const size_t to_copy = (ring_frames_avail_ < frames_per_10ms)
                                   ? ring_frames_avail_
                                   : frames_per_10ms;
        for (size_t f = 0; f < to_copy; ++f) {
          const size_t rp = ring_read_frame_ * out_channels;
          std::memcpy(feed.data() + f * out_channels,
                      ring_buf_.data() + rp,
                      out_channels * sizeof(int16_t));
          ring_read_frame_ = (ring_read_frame_ + 1) % ring_capacity_frames_;
        }
        ring_frames_avail_ -= to_copy;
      }
    }

    if (source_) {
      source_->CaptureFrame(feed.data(), /*bits_per_sample=*/16, sample_rate,
                            out_channels, frames_per_10ms);
      total_frames_del += static_cast<int64_t>(frames_per_10ms);
    }
  }

  CancelWaitableTimer(timer);
  CloseHandle(timer);
  timeEndPeriod(10);
  if (task) AvRevertMmThreadCharacteristics(task);
  CoUninitialize();
}

