// ───────── micro CUSTOM a 48 kHz (sin APM) ─────────

/// Crea una pista de micro kCustom en el nativo (fuente que NO pasa por el
/// APM, así no la degrada a 16k). Devuelve el mapa con streamId y la lista
/// audioTracks (cada track: id/label/kind/enabled), o null si el build no lo
/// soporta (flutter_webrtc estándar / plataforma sin el fork).
static Future<Map<dynamic, dynamic>?> createCustomAudioTrack() async {
  try {
    final res = await _ch.invokeMethod('createCustomAudioTrack');
    return res is Map ? res : null;
  } catch (_) {
    return null; // build sin el fork 48k
  }
}

/// Arranca el capturador nativo de micro a 48 kHz para [trackId], alimentando
/// la fuente kCustom (source->CaptureFrame). [deviceId] = entrada elegida
/// (null = predeterminado del sistema). No-op si no soportado.
/// INCIERTO: firma definida por Stage 2 (capturador PipeWire/WASAPI).
static Future<bool> startCustomMicCapture(String trackId,
    {String? deviceId, int sampleRate = 48000, int channels = 1}) async {
  try {
    await _ch.invokeMethod('startCustomMicCapture', {
      'trackId': trackId,
      if (deviceId != null) 'deviceId': deviceId,
      'sampleRate': sampleRate,
      'channels': channels,
    });
    return true;
  } catch (_) {
    return false;
  }
}

/// Para el capturador nativo de [trackId] y libera el dispositivo. No-op si no
/// soportado.
static Future<void> stopCustomMicCapture(String trackId) async {
  try {
    await _ch.invokeMethod('stopCustomMicCapture', {'trackId': trackId});
  } catch (_) {/* build sin soporte */}
}

// ───────── micro CUSTOM 48 kHz (calidad Discord, sin APM) ─────────
// Cuando está ON, el micro se publica por una pista kCustom alimentada por
// un capturador nativo a 48k (ver webrtc_apm.dart) EN VEZ de
// getUserMedia/setMicrophoneEnabled. Sin APM no hay AEC → AURICULARES.
bool fullband48k = false;
// Pista custom publicada (si el modo está activo y estamos en sala).
LocalAudioTrack? _customMicTrack;
// trackId nativo del capturador en marcha (para start/stopCustomMicCapture).
String? _customMicNativeId;

/// Opciones de captura para el track CUSTOM: stopAudioCaptureOnMute:false es
/// CLAVE — el mute de livekit por defecto llama stop()→mediaStreamTrack.stop()
/// y eso destruiría la fuente kCustom (no hay getUserMedia que la recree).
/// Sin APM no tiene sentido NS/AEC/AGC (van off; el procesado va a 48k fuera).
AudioCaptureOptions get _customMicOptions => const AudioCaptureOptions(
      noiseSuppression: false,
      echoCancellation: false,
      autoGainControl: false,
      stopAudioCaptureOnMute: false,
    );

/// Publica el micro CUSTOM a 48 kHz en la sala actual. Crea la pista kCustom
/// en el nativo, la envuelve en un LocalAudioTrack de livekit y la publica con
/// las mismas opciones de publicación que el micro normal (_micPublishOptions).
/// Arranca el capturador nativo (start...Capture) con el deviceId elegido.
/// Devuelve false (y no toca nada) si el build no soporta el modo custom: el
/// llamador hace fallback al micro normal.
Future<bool> _publishCustomMic() async {
  final lp = room?.localParticipant;
  if (lp == null) return false;

  final info = await WebrtcApm.createCustomAudioTrack();
  if (info == null) return false; // build sin fork 48k → fallback
  try {
    // Reconstruye el rtc.MediaStream nativo a partir del mapa del plugin.
    // INCIERTO: la API pública de flutter_webrtc no expone un fromMap estable;
    // si rtc.MediaStream.fromMap no existe en esta versión, el fork debe
    // exponer un helper o devolver el stream ya registrado. Ver "risks".
    final stream = await rtc.MediaStream.fromMap(
        Map<String, dynamic>.from(info as Map));
    final tracks = stream.getAudioTracks();
    if (tracks.isEmpty) return false;
    final nativeTrack = tracks.first;
    _customMicNativeId = nativeTrack.id;

    // Envuelve la pista nativa en un LocalAudioTrack de livekit (constructor
    // @internal: source, stream, track, options) — livekit_client 2.8.0.
    final lkTrack = LocalAudioTrack(
      TrackSource.microphone,
      stream,
      nativeTrack,
      _customMicOptions,
    );

    // Arranca el capturador nativo a 48k ANTES de publicar (para que ya fluya
    // PCM). deviceId = entrada elegida en ajustes.
    await WebrtcApm.startCustomMicCapture(_customMicNativeId!,
        deviceId: micDeviceId);

    // Estado de mute inicial: si entramos muteados, deshabilita la pista
    // (Track.disable() = mediaStreamTrack.enabled=false; el fork lo respeta).
    if (muted) {
      try { nativeTrack.enabled = false; } catch (_) {}
    }

    await lp.publishAudioTrack(lkTrack, publishOptions: _micPublishOptions);
    _customMicTrack = lkTrack;
    return true;
  } catch (e) {
    debugPrint('[voice] custom mic 48k falló: $e — fallback a micro normal');
    // limpia lo que se haya creado a medias
    if (_customMicNativeId != null) {
      await WebrtcApm.stopCustomMicCapture(_customMicNativeId!);
    }
    _customMicNativeId = null;
    _customMicTrack = null;
    return false;
  }
}

/// Quita la pista custom de la sala y para el capturador nativo. No re-publica
/// el micro normal (eso lo decide el llamador).
Future<void> _unpublishCustomMic() async {
  final lp = room?.localParticipant;
  final t = _customMicTrack;
  if (lp != null && t != null) {
    try {
      final pub = lp.getTrackPublicationBySource(TrackSource.microphone);
      if (pub != null && identical(pub.track, t)) {
        await lp.removePublishedTrack(pub.sid);
      }
    } catch (_) {}
  }
  if (_customMicNativeId != null) {
    await WebrtcApm.stopCustomMicCapture(_customMicNativeId!);
  }
  try { await t?.stop(); } catch (_) {}
  _customMicTrack = null;
  _customMicNativeId = null;
}

/// Activa/desactiva el modo micro 48 kHz. Persiste y, si estamos en sala,
/// re-publica el micro por la ruta correspondiente. Vuelve al micro normal si
/// el build no soporta el modo custom.
Future<void> setFullband48k(bool v) async {
  if (fullband48k == v) return;
  fullband48k = v;
  final prefs = await SharedPreferences.getInstance();
  await prefs.setBool('mic_fullband_48k', v);
  if (room?.localParticipant != null) {
    if (v) {
      // pasar de normal → custom: quita el micro normal y publica el custom
      try {
        await room?.localParticipant?.setMicrophoneEnabled(false);
      } catch (_) {}
      final ok = await _publishCustomMic();
      if (!ok) {
        fullband48k = false; // no soportado → revertir
        await prefs.setBool('mic_fullband_48k', false);
        try {
          await room?.localParticipant
              ?.setMicrophoneEnabled(!muted, audioCaptureOptions: micOptions);
        } catch (_) {}
      }
    } else {
      // custom → normal
      await _unpublishCustomMic();
      try {
        await room?.localParticipant
            ?.setMicrophoneEnabled(!muted, audioCaptureOptions: micOptions);
      } catch (_) {}
    }
  }
  notifyListeners();
}

/// Aplica el mute al micro CUSTOM sin destruir la fuente kCustom: alterna
/// mediaStreamTrack.enabled (el fork lo respeta a nivel RTP, ver
/// flutter_webrtc.cc mediaStreamTrackSetEnable). NUNCA usar mute(stopOnMute)
/// ni restartTrack en la pista custom: ambos llaman a getUserMedia/stop().
Future<void> _applyCustomMute() async {
  final t = _customMicTrack;
  if (t == null) return;
  try {
    muted ? await t.disable() : await t.enable();
  } catch (_) {}
}

try {
  if (fullband48k) {
    debugPrint('[voice] publicando micro CUSTOM 48k (mute=$muted)');
    final ok = await _publishCustomMic();
    if (!ok) {
      // build sin soporte 48k → micro normal
      fullband48k = false;
      await r.localParticipant
          ?.setMicrophoneEnabled(!muted, audioCaptureOptions: micOptions);
    }
  } else {
    debugPrint('[voice] publicando micro (mute=$muted)');
    await r.localParticipant
        ?.setMicrophoneEnabled(!muted, audioCaptureOptions: micOptions);
  }
} catch (_) {/* sin permiso SPEAK: solo escucha */}

try {
  if (fullband48k && _customMicTrack != null) {
    // micro custom: mute por enabled (no destruye la fuente kCustom)
    await _applyCustomMute();
  } else {
    // las opciones solo aplican si es la primera publicación del micro
    await room?.localParticipant
        ?.setMicrophoneEnabled(!muted, audioCaptureOptions: micOptions);
    if (!muted && _micOptionsPending) {
      // hubo cambios de opciones mientras estaba muteado: aplícalos ahora
      _micOptionsPending = false;
      await applyMicOptions();
    }
  }
} catch (_) {}

Future<void> applyMicOptions() async {
  // El micro CUSTOM 48k no usa getUserMedia: restartTrack lo destruiría. El
  // cambio de device se maneja recreando la pista en setMicDevice.
  if (fullband48k && _customMicTrack != null) return;
  final t = micTrack;

await _saveMicPrefs();
if (fullband48k && _customMicTrack != null) {
  // micro custom: el deviceId va al capturador nativo, no a getUserMedia.
  // Recrea la pista con el nuevo device (no hay replaceTrack para kCustom).
  await _unpublishCustomMic();
  await _publishCustomMic();
  notifyListeners();
  return;
}
await applyMicOptions();

// suelta refs de la pista custom (el track ya se va con la sala al disconnect)
_customMicTrack = null;
_customMicNativeId = null;

// --- Ruta de micro kCustom 48k (Stage 4) ---
// El micro custom NO pasa por el APM (que baja a 16k): un capturador nativo
// (Stage 2) entrega 48 kHz mono FULLBAND y llama a estos metodos directamente
// (no via CustomProcessing::Process). InitializeCustom48 prepara 1 motor
// RNNoise native-48 (sin resample) y marca la cadena voicefx para recrearse a
// 48k. ProcessCustom48 aplica RNNoise + voicefx + monitor in-place sobre el
// buffer 48k mono (escala FloatS16, igual que el APM): SIN band-split, SIN el
// memset de bandas altas, SIN el resample 16k<->48k.
void InitializeCustom48();
void ProcessCustom48(float* data, int num_frames);

// [chatpapol 48k] Inicializa el procesador para la ruta de micro kCustom:
// 48 kHz mono, 1 motor RNNoise native-48 (native48_ => sin resample). Reutiliza
// Initialize() con la geometria fija de la ruta custom.
void RnnoiseProcessor::InitializeCustom48() {
  Initialize(48000, 1);
}

// [chatpapol 48k] Procesa un bloque de [num_frames] muestras mono a 48 kHz
// (escala FloatS16) IN-PLACE, fuera del APM:
//   1) RNNoise sobre el buffer completo (native-48: sin resample).
//   2) cadena voicefx creada a 48k (band_rate = 48000; sin cero de bandas
//      altas porque no hay band-split: el buffer YA es fullband 48k).
//   3) monitor 'escucharme' a 48k (EmitMonitorLocked abre waveOut a rate_).
// Corre en el hilo de audio del capturador; mismo contrato realtime que Process.
void RnnoiseProcessor::ProcessCustom48(float* data, int num_frames) {
  std::lock_guard<std::mutex> lock(mu_);
  if (num_frames <= 0 || data == nullptr) return;
  // Defensa: si nunca se inicializo la geometria custom, hazlo aqui (48k/mono).
  if (rate_ != 48000 || engines_.empty()) {
    rate_ = 48000;
    if (engines_.empty()) {
      auto e = std::make_unique<RnnoiseEngine>();
      e->Reset(48000);
      engines_.push_back(std::move(e));
      chans_ = 1;
      fx_dirty_ = true;
    }
  }

  // 1) RNNoise sobre el buffer 48k (canal 0). native48_ => sin resample 16k.
  if (rnnoise_on_ && !engines_.empty() && engines_[0]) {
    engines_[0]->ProcessInPlace(data, num_frames);
  }

  // 2) voicefx a 48k (sin band-split, sin memset de bandas altas).
  const bool fx_active = fx_on_ && !fx_parsed_.empty();
  if (fx_active) {
    const int band_rate = 48000;
    if (fx_dirty_ || fx_rate_ != band_rate || fx_frames_ < num_frames ||
        fx_chains_.empty()) {
      RebuildFxLocked(band_rate, num_frames);
    }
    if (static_cast<int>(fx_scratch_.size()) < num_frames) {
      fx_scratch_.resize(num_frames);
    }
    if (!fx_chains_.empty() && fx_chains_[0]) {
      VfxChain* ch = fx_chains_[0];
      constexpr float kInv = 1.0f / 32768.0f;
      for (int i = 0; i < num_frames; ++i) fx_scratch_[i] = data[i] * kInv;
      vfx_process(ch, fx_scratch_.data(), fx_scratch_.data(), num_frames);
      for (int i = 0; i < num_frames; ++i) {
        float v = fx_scratch_[i] * 32768.0f;
        if (v > 32767.0f) v = 32767.0f;
        else if (v < -32768.0f) v = -32768.0f;
        data[i] = v;
      }
    }
  }

  // 3) Monitor: el mismo buffer 48k ya procesado (rate_=48000 => waveOut 48k).
  if (monitor_on_) EmitMonitorLocked(num_frames, data);
}
